from pathlib import Path
import hashlib,json,os,tempfile

def canonical(value):
    return json.dumps(value,sort_keys=True,separators=(",",":"),ensure_ascii=True,allow_nan=False)

def commit_shard(root,values,failpoint=None):
    # Single writer,private trusted local root;no concurrent or hostile directory support.
    if type(values) is not list or not 1<=len(values)<=32 or any(type(x) is not int or not -10000<=x<=10000 for x in values):
        raise ValueError("invalid shard values")
    if failpoint not in (None,"after-temp","after-replace"):raise ValueError("invalid failpoint")
    source={"kernel":"sum-squares-v1","values":values[:]}
    key=hashlib.sha256(canonical(source).encode("utf-8")).hexdigest()
    payload={"schema":1,"key":key,"input":source,"sum_squares":sum(x*x for x in values)}
    raw=canonical(payload)
    root=Path(root);root.mkdir(parents=True,exist_ok=True)
    final=root/(key+".json")
    if final.exists():
        if final.read_text(encoding="utf-8")!=raw:raise ValueError("conflicting or corrupt committed artifact")
        return key,"reused",payload["sum_squares"]
    temporary=None
    try:
        with tempfile.NamedTemporaryFile(mode="w",encoding="utf-8",dir=root,delete=False) as file:
            temporary=Path(file.name);file.write(raw)
        if failpoint=="after-temp":raise RuntimeError("injected before publication")
        os.replace(temporary,final)
        if failpoint=="after-replace":raise RuntimeError("injected after publication")
        return key,"committed",payload["sum_squares"]
    finally:
        if temporary is not None:temporary.unlink(missing_ok=True)

with tempfile.TemporaryDirectory() as directory:
    try:commit_shard(directory,[1,-2,3],"after-temp")
    except RuntimeError as error:print(error)
    print("artifacts",len(list(Path(directory).glob("*.json"))))
    first=commit_shard(directory,[1,-2,3]);print(first[1:])
    print(commit_shard(directory,[1,-2,3])[1:])
    try:commit_shard(directory,[4],"after-replace")
    except RuntimeError as error:print(error)
    print(commit_shard(directory,[4])[1:])
    Path(directory,first[0]+".json").write_text("corrupt",encoding="utf-8")
    try:commit_shard(directory,[1,-2,3])
    except ValueError as error:print(error)
